diff --git a/scripts/echo-args.test.js b/scripts/echo-args.test.js
new file mode 100644
index 0000000..614ac38
--- /dev/null
+++ b/scripts/echo-args.test.js
@@ -0,0 +1,18 @@
+import { describe, it, expect } from 'vitest';
+import { execSync } from 'child_process';
+import path from 'path';
+import { fileURLToPath } from 'url';
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = path.dirname(__filename);
+const scriptPath = path.join(__dirname, 'echo-args.js');
+
+describe('echo-args.js', () => {
+  it('should print all command line arguments, one per line', () => {
+    const output = execSync(`node ${scriptPath} apple banana cherry`, { encoding: 'utf-8' });
+    const expectedOutput = 'apple\nbanana\ncherry\n';
+    
+    // Normalize line endings to avoid issues across OS
+    expect(output.replace(/\r\n/g, '\n')).toBe(expectedOutput);
+  });
+});

